begin;
create table sim_murid_private.lesson_schedules(id uuid primary key default gen_random_uuid(),class_id uuid not null,academic_year_id uuid not null references public.academic_years(id),subject_id uuid not null references public.subjects(id),teacher_id uuid not null references public.profiles(id),weekday smallint not null check(weekday between 1 and 7),start_minute integer not null check(start_minute between 0 and 1439),duration_minutes integer not null check(duration_minutes between 1 and 240),jtm integer not null check(jtm between 1 and 12),break_minutes integer not null default 0 check(break_minutes between 0 and 240),end_minute integer generated always as(start_minute+duration_minutes*jtm+break_minutes) stored,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz,foreign key(class_id,academic_year_id) references public.classes(id,academic_year_id),check(end_minute>start_minute and end_minute<1440));
create index lesson_schedules_class_day on sim_murid_private.lesson_schedules(class_id,academic_year_id,weekday,start_minute) where archived_at is null;
create index lesson_schedules_teacher_day on sim_murid_private.lesson_schedules(teacher_id,academic_year_id,weekday,start_minute) where archived_at is null;
create index lesson_schedules_year on sim_murid_private.lesson_schedules(academic_year_id);
create index lesson_schedules_subject on sim_murid_private.lesson_schedules(subject_id);
create index lesson_schedules_actor on sim_murid_private.lesson_schedules(created_by);
create table sim_murid_private.student_duty_assignments(id uuid primary key default gen_random_uuid(),class_id uuid not null,academic_year_id uuid not null references public.academic_years(id),student_id uuid not null references public.profiles(id),weekday smallint not null check(weekday between 1 and 7),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),archived_at timestamptz,foreign key(class_id,academic_year_id) references public.classes(id,academic_year_id));
create unique index student_duty_current on sim_murid_private.student_duty_assignments(class_id,weekday,student_id) where archived_at is null;
create index student_duty_year on sim_murid_private.student_duty_assignments(academic_year_id);
create index student_duty_student on sim_murid_private.student_duty_assignments(student_id);
create index student_duty_actor on sim_murid_private.student_duty_assignments(created_by);
do $$ declare t text;begin foreach t in array array['lesson_schedules','student_duty_assignments'] loop execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on table sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on table sim_murid_private.%I to service_role',t);end loop;end $$;
create function public.app_schedules_read(p_actor uuid,p_session uuid,p_year uuid default null,p_class uuid default null,p_weekday integer default null,p_personal boolean default false) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare role text;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return null;end if;
 if p_weekday is not null and p_weekday not between 1 and 7 then return null;end if;
 select role_code into role from public.user_roles where user_id=p_actor;
 return jsonb_build_object('revision',(select revision from sim_murid_private.education_state),'today',(extract(isodow from(now() at time zone 'Asia/Jakarta')))::integer,
 'lessons',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'class_id',c.id,'class_name',c.name,'year_id',l.academic_year_id,'subject_id',s.id,'subject',s.name,'teacher_id',p.id,'teacher_name',p.full_name,'weekday',l.weekday,'start_minute',l.start_minute,'duration_minutes',l.duration_minutes,'jtm',l.jtm,'break_minutes',l.break_minutes,'end_minute',l.end_minute,'can_manage',public.app_class_access(p_actor,p_session,c.id,true)) order by l.weekday,l.start_minute,c.name,l.id),'[]') from sim_murid_private.lesson_schedules l join public.classes c on c.id=l.class_id join public.academic_years y on y.id=l.academic_year_id join public.subjects s on s.id=l.subject_id join public.profiles p on p.id=l.teacher_id where l.archived_at is null and c.archived_at is null and (case when p_year is null then y.is_active else l.academic_year_id=p_year end) and(p_class is null or l.class_id=p_class) and(p_weekday is null or l.weekday=p_weekday) and public.app_class_access(p_actor,p_session,c.id,false) and(not p_personal or role<>'teacher' or l.teacher_id=p_actor)),
 'duties',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'class_id',c.id,'class_name',c.name,'student_id',p.id,'student_name',p.full_name,'weekday',d.weekday,'can_manage',public.app_class_access(p_actor,p_session,c.id,true)) order by d.weekday,p.full_name,d.id),'[]') from sim_murid_private.student_duty_assignments d join public.classes c on c.id=d.class_id join public.academic_years y on y.id=d.academic_year_id join public.profiles p on p.id=d.student_id where d.archived_at is null and c.archived_at is null and p.status='active' and exists(select 1 from sim_murid_private.enrollments e where e.student_id=d.student_id and e.class_id=d.class_id and e.ended_at is null) and(case when p_year is null then y.is_active else d.academic_year_id=p_year end) and(p_class is null or d.class_id=p_class) and(p_weekday is null or d.weekday=p_weekday) and public.app_class_access(p_actor,p_session,c.id,false)),
 'duty_roster',(select coalesce(jsonb_agg(jsonb_build_object('class_id',d.class_id,'student_id',d.student_id,'weekday',d.weekday)),'[]') from sim_murid_private.student_duty_assignments d join public.classes c on c.id=d.class_id join public.academic_years y on y.id=d.academic_year_id where d.archived_at is null and c.archived_at is null and(case when p_year is null then y.is_active else d.academic_year_id=p_year end) and public.app_class_access(p_actor,p_session,c.id,true)),
 'subjects',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'active',active) order by sort_order),'[]') from public.subjects),
 'teachers',case when exists(select 1 from public.classes c where public.app_class_access(p_actor,p_session,c.id,true)) then(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name) order by p.full_name,p.id),'[]') from public.profiles p join public.user_roles r on r.user_id=p.id where p.status='active' and r.role_code='teacher') else '[]'::jsonb end);
end;$$;
create function public.app_schedules_write(p_actor uuid,p_session uuid,p_request uuid,p_revision bigint,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare version bigint;old sim_murid_private.education_requests%rowtype;target uuid;class uuid;previous_class uuid;y uuid;teacher uuid;subject uuid;startmin integer;endmin integer;day integer;duration integer;units integer;rest integer;item jsonb;lesson_ids uuid[];duty_ids uuid[];result jsonb;begin
 perform 1 from public.profiles where id=p_actor for share;perform 1 from public.user_roles where user_id=p_actor for share;
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 select revision into version from sim_murid_private.education_state for update;
 select * into old from sim_murid_private.education_requests where id=p_request;
 if found then if old.actor=p_actor and old.command=p_command then return old.result;end if;return jsonb_build_object('code','request_conflict');end if;
 if version is distinct from p_revision then return jsonb_build_object('code','stale');end if;
 if p_command->>'type' in('lesson','duties') then
  class=(p_command->>'classId')::uuid;
  if not public.app_class_access(p_actor,p_session,class,true) then return jsonb_build_object('code','denied');end if;
  select academic_year_id into y from public.classes where id=class and archived_at is null;if y is null then return jsonb_build_object('code','not_found');end if;
 end if;
 if p_command->>'type'='lesson' then
  target=(p_command->>'id')::uuid;teacher=(p_command->>'teacherId')::uuid;subject=(p_command->>'subjectId')::uuid;day=(p_command->>'weekday')::integer;duration=(p_command->>'durationMinutes')::integer;units=(p_command->>'jtm')::integer;rest=(p_command->>'breakMinutes')::integer;
  if p_command->>'start'!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or day not between 1 and 7 or duration not between 1 and 240 or units not between 1 and 12 or rest not between 0 and 240 then return jsonb_build_object('code','invalid');end if;
  startmin=split_part(p_command->>'start',':',1)::integer*60+split_part(p_command->>'start',':',2)::integer;endmin=startmin+duration*units+rest;
  if endmin>=1440 or not exists(select 1 from public.profiles p join public.user_roles r on r.user_id=p.id where p.id=teacher and p.status='active' and r.role_code='teacher') or not exists(select 1 from public.subjects where id=subject and active) then return jsonb_build_object('code','invalid');end if;
  if target is not null then select class_id into previous_class from sim_murid_private.lesson_schedules where id=target and archived_at is null;if previous_class is null then return jsonb_build_object('code','not_found');end if;if not public.app_class_access(p_actor,p_session,previous_class,true) then return jsonb_build_object('code','denied');end if;end if;
  if exists(select 1 from sim_murid_private.lesson_schedules l join public.classes c on c.id=l.class_id where l.academic_year_id=y and l.weekday=day and l.archived_at is null and c.archived_at is null and l.id is distinct from target and(l.class_id=class or l.teacher_id=teacher) and l.start_minute<endmin and l.end_minute>startmin) then return jsonb_build_object('code','overlap');end if;
  if target is null then insert into sim_murid_private.lesson_schedules(class_id,academic_year_id,subject_id,teacher_id,weekday,start_minute,duration_minutes,jtm,break_minutes,created_by) values(class,y,subject,teacher,day,startmin,duration,units,rest,p_actor) returning id into target;
  else update sim_murid_private.lesson_schedules set class_id=class,academic_year_id=y,subject_id=subject,teacher_id=teacher,weekday=day,start_minute=startmin,duration_minutes=duration,jtm=units,break_minutes=rest,updated_at=now() where id=target;end if;
 elsif p_command->>'type'='duties' then
  if jsonb_typeof(p_command->'items') is distinct from 'array' or jsonb_array_length(p_command->'items')>500 then return jsonb_build_object('code','invalid');end if;
  if exists(select 1 from jsonb_array_elements(p_command->'items')x group by x->>'studentId',x->>'weekday' having count(*)>1) then return jsonb_build_object('code','duplicate');end if;
  for item in select value from jsonb_array_elements(p_command->'items') loop
   if (item->>'weekday')::integer not between 1 and 7 or not exists(select 1 from sim_murid_private.enrollments e join public.profiles p on p.id=e.student_id join public.user_roles r on r.user_id=p.id where e.class_id=class and e.student_id=(item->>'studentId')::uuid and e.ended_at is null and r.role_code='student' and p.status='active') then return jsonb_build_object('code','invalid_membership');end if;
  end loop;
  update sim_murid_private.student_duty_assignments set archived_at=now() where class_id=class and archived_at is null;
  insert into sim_murid_private.student_duty_assignments(class_id,academic_year_id,student_id,weekday,created_by) select class,y,(x->>'studentId')::uuid,(x->>'weekday')::integer,p_actor from jsonb_array_elements(p_command->'items')x;target=class;
 elsif p_command->>'type'='schedule_delete' then
  lesson_ids=array(select jsonb_array_elements_text(p_command->'lessonIds')::uuid);duty_ids=array(select jsonb_array_elements_text(p_command->'dutyIds')::uuid);
  if cardinality(lesson_ids)+cardinality(duty_ids) not between 1 and 500 or cardinality(lesson_ids)<>(select count(distinct x) from unnest(lesson_ids)x) or cardinality(duty_ids)<>(select count(distinct x) from unnest(duty_ids)x) then return jsonb_build_object('code','invalid');end if;
  if (select count(*) from sim_murid_private.lesson_schedules where id=any(lesson_ids) and archived_at is null)<>cardinality(lesson_ids) or(select count(*) from sim_murid_private.student_duty_assignments where id=any(duty_ids) and archived_at is null)<>cardinality(duty_ids) then return jsonb_build_object('code','not_found');end if;
  if exists(select 1 from sim_murid_private.lesson_schedules where id=any(lesson_ids) and not public.app_class_access(p_actor,p_session,class_id,true)) or exists(select 1 from sim_murid_private.student_duty_assignments where id=any(duty_ids) and not public.app_class_access(p_actor,p_session,class_id,true)) then return jsonb_build_object('code','denied');end if;
  update sim_murid_private.lesson_schedules set archived_at=now(),updated_at=now() where id=any(lesson_ids);update sim_murid_private.student_duty_assignments set archived_at=now() where id=any(duty_ids);
 else return jsonb_build_object('code','invalid');end if;
 update sim_murid_private.education_state set revision=revision+1;
 result=jsonb_build_object('code','saved','id',target);insert into sim_murid_private.education_requests(id,actor,target,command,result) values(p_request,p_actor,target,p_command,result);
 insert into sim_murid_private.activity_logs(actor_id,actor_kind,action,entity_type,entity_id,request_id) values(p_actor,'user','schedules.'||(p_command->>'type'),'schedule',target,p_request);
 return result;
exception when unique_violation then return jsonb_build_object('code','duplicate');when invalid_text_representation or check_violation or not_null_violation then return jsonb_build_object('code','invalid');end;$$;
revoke all on function public.app_schedules_read(uuid,uuid,uuid,uuid,integer,boolean),public.app_schedules_write(uuid,uuid,uuid,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.app_schedules_read(uuid,uuid,uuid,uuid,integer,boolean),public.app_schedules_write(uuid,uuid,uuid,bigint,jsonb) to service_role;
commit;
